$ErrorActionPreference = "Stop"

$Repo = "D:\MT5_Backtests\guardian-autonomous-main"
$Dest = Join-Path $Repo "research\standards"
$Lake = "D:\MT5_Backtests\Research\KnowledgeBase\observations\1.0.0"

$ExpectedBundleHash = "df2750fbba80a873cba489b29d13a548bc798eb5490575a5ec814f920514f210"

$BundleB64 = @'

'@

$TmpRoot = Join-Path $env:TEMP ("guardian_research_standard_v1_" + [guid]::NewGuid().ToString("N"))
$TmpZip  = Join-Path $TmpRoot "guardian_research_standard_v1.zip"
$TmpOut  = Join-Path $TmpRoot "expanded"

New-Item -ItemType Directory -Force -Path $TmpRoot | Out-Null
New-Item -ItemType Directory -Force -Path $TmpOut | Out-Null

try {
    [IO.File]::WriteAllBytes(
        $TmpZip,
        [Convert]::FromBase64String($BundleB64)
    )

    $actualBundleHash = (Get-FileHash $TmpZip -Algorithm SHA256).Hash.ToLower()

    if ($actualBundleHash -ne $ExpectedBundleHash) {
        throw "Bundle SHA256 mismatch."
    }

    Expand-Archive -Path $TmpZip -DestinationPath $TmpOut -Force

    $sumFile = Join-Path $TmpOut "SHA256SUMS.json"

    if (-not (Test-Path $sumFile)) {
        throw "SHA256SUMS.json missing from bundle."
    }

    $sums = Get-Content $sumFile -Raw | ConvertFrom-Json

    foreach ($p in $sums.PSObject.Properties) {
        $name = $p.Name
        $expected = [string]$p.Value
        $path = Join-Path $TmpOut $name

        if (-not (Test-Path $path)) {
            throw "Missing canonical file in bundle: $name"
        }

        $actual = (Get-FileHash $path -Algorithm SHA256).Hash.ToLower()

        if ($actual -ne $expected.ToLower()) {
            throw "Internal hash mismatch: $name"
        }
    }

    New-Item -ItemType Directory -Force -Path $Dest | Out-Null
    New-Item -ItemType Directory -Force -Path $Lake | Out-Null

    foreach ($src in Get-ChildItem $TmpOut -File) {
        $dst = Join-Path $Dest $src.Name

        if (Test-Path $dst) {
            $existing = (Get-FileHash $dst -Algorithm SHA256).Hash.ToLower()
            $incoming = (Get-FileHash $src.FullName -Algorithm SHA256).Hash.ToLower()

            if ($existing -ne $incoming) {
                throw "REFUSING TO OVERWRITE DIFFERENT CANONICAL FILE: $dst"
            }

            continue
        }

        Copy-Item $src.FullName $dst
    }

    $py = Get-Command python -ErrorAction SilentlyContinue

    if ($null -ne $py) {
        & python -m py_compile (Join-Path $Dest "guardian_observation_v1.py")
        if ($LASTEXITCODE -ne 0) {
            throw "guardian_observation_v1.py syntax check failed"
        }

        $smoke = & python (Join-Path $Dest "guardian_observation_v1.py")
        $smoke
    } else {
        "WARNING: python command not found; files installed but Python smoke test skipped."
    }

    "`n============================================================"
    " GUARDIAN RESEARCH STANDARD V1 INSTALLED"
    "============================================================"
    "STANDARDS : $Dest"
    "DATA LAKE : $Lake"
    "BUNDLE    : $actualBundleHash"
    "STATUS    : CANONICAL"
    "============================================================"
}
finally {
    if (Test-Path $TmpRoot) {
        Remove-Item $TmpRoot -Recurse -Force
    }
}
